head.script:
scwin.onpageload = function() {
    scwin.trigger1_onclick();
    scwin.trigger2_onclick();
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var jsonData1 = [{
            "col1": "11",
            "col2": "1",
            "col3": "a",
            "col4": "aa"
        },
        {
            "col1": "12",
            "col2": "2",
            "col3": "b",
            "col4": "bb"
        },
        {
            "col1": "13",
            "col2": "3",
            "col3": "c",
            "col4": "cc"
        },
        {
            "col1": "14",
            "col2": "4",
            "col3": "d",
            "col4": "dd"
        },
        {
            "col1": "15",
            "col2": "5",
            "col3": "e",
            "col4": "ee"
        },
        {
            "col1": "16",
            "col2": "6",
            "col3": "f",
            "col4": "통합<font color='#ff0000'>테스트</font> 지원"
        },
        {
            "col1": "17",
            "col2": "7",
            "col3": "g",
            "col4": "gg",
            "col5": "히든"
        },
    ];
    dataList1.setJSON(jsonData1);
};
scwin.trigger2_onclick = function(e) {
    gridView1.mergeCell({
        "rowIndex": 1,
        "colIndex": 1,
        "colSpan": 2,
        "rowSpan": 4
    });
};
scwin.trigger5_onclick = function(e) {
    gridView1.mergeCell({
        "rowIndex": 1,
        "colIndex": 1,
        "colSpan": 2,
        "rowSpan": 3
    });
};
scwin.select1_onchange = function() {
    if (select1.getValue() == "1") {
        gridView1.setRowVisible(2, false);
    } else {
        gridView1.setRowVisible(2, true);
        gridView1.setRowVisible(3, true);
    }
};
scwin.select2_onchange = function() {
    if (select2.getValue() == "1") {
        gridView1.setRowVisible(2, false);
        gridView1.setRowVisible(3, false);
        gridView1.setRowVisible(4, false);
    } else {
        gridView1.setRowVisible(2, true);
        gridView1.setRowVisible(3, true);
        gridView1.setRowVisible(4, true);
    }
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('select1_input_0').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_5_1').style.display == ''", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
